patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..7210069
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,38 @@
+"use strict";
+// Repro for no-var autofix turning working `var` code into code that throws a
+// TDZ ReferenceError. Usage: node repro/no-var-tdz.js [path/to/eslint/lib/api]
+const path = require("node:path");
+const vm = require("node:vm");
+const apiPath = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "../lib/api");
+const { Linter } = require(apiPath);
+const linter = new Linter({ configType: "flat" });
+const config = [{ rules: { "no-var": "error" } }];
+
+function run(code) {
+	try { vm.runInNewContext(code, { console: { log() {} } }); return "ok"; }
+	catch (e) { return `${e.name}: ${e.message}`; }
+}
+
+const cases = {
+	"issue snippet (use before var)": `function a() {\n    console.log(o);\n    var o;\n    return o;\n}\na();`,
+	"hoisted fn called directly": `f();\nvar o = 1;\nfunction f() { return o; }`,
+	"hoisted fn called via new": `new F();\nvar o = 1;\nfunction F() { o; }`,
+	"hoisted fn called via .call": `f.call(null);\nvar o = 1;\nfunction f() { return o; }`,
+	"hoisted fn passed as callback": `[1].forEach(f);\nvar o = 1;\nfunction f() { return o; }`,
+	"hoisted fn as tagged template": "f``;\nvar o = 1;\nfunction f() { return o; }",
+	"hoisted fn called through another hoisted fn": `g();\nvar o = 1;\nfunction f() { return o; }\nfunction g() { return f(); }`,
+	"hoisted fn aliased then called": `const h = f;\nh();\nvar o = 1;\nfunction f() { return o; }`,
+};
+
+console.log(`eslint ${require(path.join(apiPath, "../../package.json")).version} (${apiPath})\n`);
+let broken = 0;
+for (const [name, code] of Object.entries(cases)) {
+	const { output, fixed } = linter.verifyAndFix(code, config, { filename: "x.js" });
+	const before = run(code), after = fixed ? run(output) : before;
+	const bad = before === "ok" && after !== "ok";
+	if (bad) broken++;
+	console.log(`${bad ? "BUG " : "ok  "} ${name}: fixed=${fixed}, original=${before}, after fix=${after}`);
+	if (bad) console.log(output.replace(/^/gm, "       | "));
+}
+console.log(`\n${broken} case(s) where the no-var autofix introduced a runtime error`);
+process.exitCode = broken ? 1 : 0;
